import{_ as s,o as n,c as d,ah as e,j as a}from"./chunks/framework.sPHStHqt.js";const g=JSON.parse('{"title":"Multi-Database","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/multi-database.md","filePath":"getting-started/multi-database.md","lastUpdated":1789630599000}'),o={name:"getting-started/multi-database.md"};function i(r,t,l,c,h,u){return n(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="multi-database" tabindex="-1" data-v-1e63451c>Multi-Database <a class="header-anchor" href="#multi-database" aria-label="Permalink to &quot;Multi-Database&quot;" data-v-1e63451c>​</a></h1><p data-v-1e63451c>Krayin&#39;s Multi-Tenant SaaS comes in <strong data-v-1e63451c>two flavours</strong>, and they differ in exactly one thing: <em data-v-1e63451c>where each tenant&#39;s data is stored</em>. This guide documents the <strong data-v-1e63451c>single-database</strong> edition — the one running at your platform. This page explains the <strong data-v-1e63451c>multi-database</strong> edition, so you can tell which model you have and understand the trade-off.</p><div class="info custom-block" data-v-1e63451c><p class="custom-block-title" data-v-1e63451c>What you&#39;ll learn</p><ul data-v-1e63451c><li data-v-1e63451c>The difference between the single-database and multi-database editions</li><li data-v-1e63451c>How the multi-database model isolates each tenant</li><li data-v-1e63451c>The advantages and the costs of a database per tenant</li><li data-v-1e63451c>Which model suits which kind of platform</li></ul></div><h2 id="two-ways-to-separate-tenants" tabindex="-1" data-v-1e63451c>Two ways to separate tenants <a class="header-anchor" href="#two-ways-to-separate-tenants" aria-label="Permalink to &quot;Two ways to separate tenants&quot;" data-v-1e63451c>​</a></h2><p data-v-1e63451c>Every SaaS has to keep one tenant&#39;s data from leaking into another&#39;s. Krayin offers two ways to do it:</p><ul data-v-1e63451c><li data-v-1e63451c><strong data-v-1e63451c>Single-database</strong> <em data-v-1e63451c>(this guide)</em> — one shared database. Every tenant-owned row carries a <code data-v-1e63451c>company_id</code>, and the platform limits every query to the signed-in tenant&#39;s own rows. Separation is enforced in software. See <a href="/getting-started/architecture" data-v-1e63451c>How It Works</a>.</li><li data-v-1e63451c><strong data-v-1e63451c>Multi-database</strong> — <strong data-v-1e63451c>a separate database for every tenant</strong>. There&#39;s no shared table to leak from, because each tenant&#39;s data physically lives in its own database.</li></ul><p data-v-1e63451c>The super-admin experience is nearly identical either way — the same tenants, plans, subscriptions and cross-tenant views. What changes is what&#39;s happening underneath.</p><h2 id="how-multi-database-works" tabindex="-1" data-v-1e63451c>How multi-database works <a class="header-anchor" href="#how-multi-database-works" aria-label="Permalink to &quot;How multi-database works&quot;" data-v-1e63451c>​</a></h2><p data-v-1e63451c>A small <strong data-v-1e63451c>central database</strong> holds the platform&#39;s own records — the list of tenants, the plans, invoices and settings. Each <strong data-v-1e63451c>tenant</strong> then gets a database of its own, holding only <em data-v-1e63451c>their</em> CRM data.</p><p data-v-1e63451c>When a request comes in, the platform reads the address (<code data-v-1e63451c>acme.yourplatform.com</code>), works out which tenant it belongs to, and connects to <em data-v-1e63451c>that tenant&#39;s</em> database for the rest of the request. The super admin, meanwhile, works against the central database and can read across all the tenant databases for its platform-wide views.</p>',10),a("figure",{class:"arch-figure"},[a("svg",{class:"arch-diagram",viewBox:"0 0 720 420",role:"img","aria-labelledby":"arch-title arch-desc",xmlns:"http://www.w3.org/2000/svg"},[a("title",{id:"arch-title"},"Multi-database architecture"),a("desc",{id:"arch-desc"},"A request is routed by domain to a tenant-specific database. A central database holds platform records and is used by the super admin."),a("g",{class:"node node-accent"},[a("rect",{x:"24",y:"28",width:"150",height:"56",rx:"10"}),a("text",{x:"99",y:"52",class:"t-title"},"Super Admin"),a("text",{x:"99",y:"70",class:"t-sub"},"platform panel")]),a("g",{class:"node"},[a("rect",{x:"285",y:"24",width:"150",height:"64",rx:"10"}),a("text",{x:"360",y:"48",class:"t-title"},"Request"),a("text",{x:"360",y:"66",class:"t-sub"},"acme.yourplatform.com")]),a("g",{class:"node node-router"},[a("path",{d:"M360 150 L432 186 L360 222 L288 186 Z"}),a("text",{x:"360",y:"182",class:"t-title"},"Route by"),a("text",{x:"360",y:"198",class:"t-title"},"domain")]),a("g",{class:"node node-central"},[a("rect",{x:"520",y:"30",width:"176",height:"72",rx:"10"}),a("text",{x:"608",y:"54",class:"t-title"},"Central database"),a("text",{x:"608",y:"74",class:"t-sub"},"tenants · plans"),a("text",{x:"608",y:"90",class:"t-sub"},"invoices · settings")]),a("g",{class:"node node-tenant"},[a("rect",{x:"40",y:"320",width:"176",height:"72",rx:"10"}),a("text",{x:"128",y:"344",class:"t-title"},"Acme database"),a("text",{x:"128",y:"364",class:"t-sub"},"their leads, quotes,"),a("text",{x:"128",y:"380",class:"t-sub"},"contacts")]),a("g",{class:"node node-tenant"},[a("rect",{x:"272",y:"320",width:"176",height:"72",rx:"10"}),a("text",{x:"360",y:"344",class:"t-title"},"Northwind database"),a("text",{x:"360",y:"364",class:"t-sub"},"their leads, quotes,"),a("text",{x:"360",y:"380",class:"t-sub"},"contacts")]),a("g",{class:"node node-tenant"},[a("rect",{x:"504",y:"320",width:"176",height:"72",rx:"10"}),a("text",{x:"592",y:"344",class:"t-title"},"Meridian database"),a("text",{x:"592",y:"364",class:"t-sub"},"their leads, quotes,"),a("text",{x:"592",y:"380",class:"t-sub"},"contacts")]),a("g",{class:"edge"},[a("line",{x1:"360",y1:"88",x2:"360",y2:"150"}),a("line",{x1:"174",y1:"56",x2:"520",y2:"60",class:"edge-dashed"}),a("line",{x1:"330",y1:"210",x2:"160",y2:"320"}),a("line",{x1:"360",y1:"222",x2:"360",y2:"320"}),a("line",{x1:"390",y1:"210",x2:"560",y2:"320"})])]),a("figcaption",null,"Each tenant's CRM data lives in its own database; a small central database holds the platform's records.")],-1),e('<p data-v-1e63451c>The dashed line marks the super admin reading the central database; the solid lines show a tenant&#39;s request being routed to its own database.</p><h2 id="what-a-tenant-gets-either-way" tabindex="-1" data-v-1e63451c>What a tenant gets, either way <a class="header-anchor" href="#what-a-tenant-gets-either-way" aria-label="Permalink to &quot;What a tenant gets, either way&quot;" data-v-1e63451c>​</a></h2><p data-v-1e63451c>From the tenant&#39;s seat, the two editions feel the same: their own subdomain, their own CRM, their own team, and data no one else can see. A tenant never needs to know which model powers the platform. Everything in the <a href="/tenants/registration" data-v-1e63451c>Tenants</a> section applies to both.</p><h2 id="advantages-of-a-database-per-tenant" tabindex="-1" data-v-1e63451c>Advantages of a database per tenant <a class="header-anchor" href="#advantages-of-a-database-per-tenant" aria-label="Permalink to &quot;Advantages of a database per tenant&quot;" data-v-1e63451c>​</a></h2><ul data-v-1e63451c><li data-v-1e63451c><strong data-v-1e63451c>Maximum isolation.</strong> There is no shared table, so one tenant&#39;s data can never appear in another&#39;s queries — separation is physical, not just enforced in code.</li><li data-v-1e63451c><strong data-v-1e63451c>Per-tenant backup and restore.</strong> You can back up, restore or migrate a single tenant without touching the others.</li><li data-v-1e63451c><strong data-v-1e63451c>Independent scaling.</strong> A heavy tenant can be moved to its own database server without affecting anyone else.</li><li data-v-1e63451c><strong data-v-1e63451c>Cleaner compliance.</strong> Data-residency and &quot;delete all my data&quot; requests are simpler when a tenant&#39;s data is a self-contained database.</li></ul><h2 id="things-to-keep-in-mind" tabindex="-1" data-v-1e63451c>Things to keep in mind <a class="header-anchor" href="#things-to-keep-in-mind" aria-label="Permalink to &quot;Things to keep in mind&quot;" data-v-1e63451c>​</a></h2><ul data-v-1e63451c><li data-v-1e63451c><strong data-v-1e63451c>More databases to run.</strong> Maintenance — upgrades, backups, monitoring — scales with the number of tenants, not with one shared database.</li><li data-v-1e63451c><strong data-v-1e63451c>Higher infrastructure cost.</strong> Many databases cost more to host than one.</li><li data-v-1e63451c><strong data-v-1e63451c>Slower sign-up.</strong> A new tenant&#39;s database has to be created and a full CRM installed into it before they can sign in — this runs in the background and takes a moment, where the single-database edition is instant.</li><li data-v-1e63451c><strong data-v-1e63451c>Database-creation privileges.</strong> The platform&#39;s database user must be allowed to create and drop databases.</li></ul><h2 id="which-model-should-you-run" tabindex="-1" data-v-1e63451c>Which model should you run? <a class="header-anchor" href="#which-model-should-you-run" aria-label="Permalink to &quot;Which model should you run?&quot;" data-v-1e63451c>​</a></h2><table tabindex="0" data-v-1e63451c><thead data-v-1e63451c><tr data-v-1e63451c><th data-v-1e63451c></th><th data-v-1e63451c>Single-database <em data-v-1e63451c>(this guide)</em></th><th data-v-1e63451c>Multi-database</th></tr></thead><tbody data-v-1e63451c><tr data-v-1e63451c><td data-v-1e63451c>Data separation</td><td data-v-1e63451c>One shared DB, scoped by <code data-v-1e63451c>company_id</code></td><td data-v-1e63451c>A separate DB per tenant</td></tr><tr data-v-1e63451c><td data-v-1e63451c>Best for</td><td data-v-1e63451c>Many smaller tenants, lowest cost</td><td data-v-1e63451c>Fewer, larger tenants needing hard isolation</td></tr><tr data-v-1e63451c><td data-v-1e63451c>Sign-up speed</td><td data-v-1e63451c>Instant</td><td data-v-1e63451c>A short provisioning wait</td></tr><tr data-v-1e63451c><td data-v-1e63451c>Ops overhead</td><td data-v-1e63451c>One database</td><td data-v-1e63451c>One per tenant</td></tr><tr data-v-1e63451c><td data-v-1e63451c>Isolation</td><td data-v-1e63451c>Enforced in software</td><td data-v-1e63451c>Physical</td></tr></tbody></table><p data-v-1e63451c>Neither is &quot;better&quot; — they suit different businesses. If you&#39;re running many small tenants and want the simplest, cheapest setup, single-database is the natural fit. If you have a smaller number of larger customers who need their data physically apart, multi-database earns its extra overhead.</p><div class="tip custom-block" data-v-1e63451c><p class="custom-block-title" data-v-1e63451c>The multi-database edition</p><p data-v-1e63451c>The multi-database product is a separate Krayin extension with its own provisioning, email-OTP registration and per-tenant SMTP. Its full write-up lives on Webkul&#39;s blog: <a href="https://webkul.com/blog/user-guide-for-krayin-crm-multidb-sass/" target="_blank" rel="noreferrer" data-v-1e63451c>User Guide for Krayin CRM Multi-DB SaaS</a>.</p></div><h2 id="where-to-go-next" tabindex="-1" data-v-1e63451c>Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;" data-v-1e63451c>​</a></h2><ul data-v-1e63451c><li data-v-1e63451c>How the single-database edition keeps tenants apart → <a href="/getting-started/architecture" data-v-1e63451c>How It Works</a></li><li data-v-1e63451c>What every tenant gets, on either model → <a href="/tenants/tenant-workspace" data-v-1e63451c>The Tenant Workspace</a></li><li data-v-1e63451c>Stand your platform up → <a href="/getting-started/installation" data-v-1e63451c>Installation</a></li></ul>',13)])])}const b=s(o,[["render",i],["__scopeId","data-v-1e63451c"]]);export{g as __pageData,b as default};
